  "<table class=\"elenco\"><tr><th>Mezzo</th><th>Merce</th><th>Stato</th><th class=\"num\">Ricavi {0}</th><th class=\"num\">Costi {1}</th><th class=\"num\">Profitto {2}</th><th class=\"num\">Profitto anno scorso</th><th class=\"num\">Età</th></tr>": "<table class=\"elenco\"><tr><th>Vehicle</th><th>Cargo</th><th>Status</th><th class=\"num\">Revenue {0}</th><th class=\"num\">Costs {1}</th><th class=\"num\">Profit {2}</th><th class=\"num\">Profit last year</th><th class=\"num\">Age</th></tr>",
